BEGIN TRANSACTION;

SELECT DISTINCT r.firstName, r.lastName, r.email
FROM #reviews r
WHERE NOT EXISTS (SELECT 1 FROM dbo.customers c WHERE c.email = r.email);

SELECT r.feedbackContent, r.submitted, c.customerID, r.rating
FROM #reviews r
JOIN dbo.customers c ON c.email = r.email
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.feedbacklog f
    WHERE f.customerID = c.customerID AND f.feedbackContent = r.feedbackContent);

COMMIT TRANSACTION;

DROP TABLE #reviews;
GO
